CREATE OR REPLACE FUNCTION public.can_edit_checklist_templates(p_org_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
           SELECT 1
             FROM public.organization_members m
            WHERE m.organization_id = p_org_id
              AND m.user_id = (SELECT auth.uid())
              AND m.role IN ('admin', 'it_admin')
         )
     AND COALESCE((public.check_feature_access(p_org_id, 'transaction_checklists') ->> 'allowed')::boolean, false);
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public.can_edit_checklist_templates(uuid)'::regprocedure) NOT LIKE '%''broker''%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('broker removed') AS mutation;
